SELECT c.id, c.knowledge_id AS knowledgeId, c.doc_id AS docId, d.doc_title AS docTitle, c.chunk_no AS chunkNo, LEFT(c.chunk_content, 200) AS chunkContent, c.chunk_token_count AS chunkTokenCount, c.vector_id AS vectorId, c.embed_status AS embedStatus, c.recall_count AS recallCount, c.status, c.create_time AS createTime FROM bedrock_ai_knowledge_chunk c LEFT JOIN bedrock_ai_knowledge_doc d ON c.doc_id = d.id AND d.is_deleted = 0 WHERE c.is_deleted = 0
AND c.knowledge_id = #{param.knowledgeId}
AND c.doc_id = #{param.docId}
AND c.embed_status = #{param.embedStatus}
AND c.status = #{param.status}
ORDER BY c.doc_id ASC, c.chunk_no ASC
